template.script:
$(document).ready(function() {
    // Function to check URL and redirect if needed
    function checkAndRedirect() {
        // Only redirect if we're on the main web page with no specific action
        if (window.location.pathname === '/web' && 
            (window.location.hash === '' || 
             window.location.hash === '#' || 
             window.location.hash === '#home')) {

            // Redirect to the apps menu
            window.location.hash = 'menu_id=apps';
        }
    }

    // First check - might miss if Odoo is still loading
    checkAndRedirect();

    // Second check - after a delay to ensure Odoo is fully loaded
    setTimeout(checkAndRedirect, 500);
});
